from __future__ import absolute_import
import time
import psutil
import logging
from selenium.webdriver.common.by import By
from selenium.common.exceptions import TimeoutException
from taf.selenium.sbts.pages.panels.view import ViewPanel
from taf.selenium.sbts.pages.navigatable_page import NavigatablePage
from taf.selenium.sbts.pages.modals import (AbortSoftwareDownloadModal, RollbackSoftwareModal,
                                            WebElementManagerReloadModal)


class Software(object):
    """
    The class corresponding to software page on selenium_sbts web, all operations under software
    page will be implemented or added in its corresponding classes.
    """

    def __init__(self, driver, download_checker):
        self._software_update = SoftwareUpdatePage(driver, download_checker)
        self._antenna_line_devices_sw = AntennaLineDevicesSoftwarePage(driver, download_checker)
        self._beam_set_realization_software = BeamSetRealizationSoftwarePage(driver, download_checker)

    @property
    def software_update(self):
        return self._software_update

    @property
    def antenna_line_devices_sw(self):
        return self._antenna_line_devices_sw

    @property
    def beam_set_realization_software(self):
        return self._beam_set_realization_software


class SoftwareUpdatePage(NavigatablePage):
    _MENU_ROUTE_LIST = ['Software', 'Software Management', 'Software Update']

    def __init__(self, driver, download_checker):
        super(SoftwareUpdatePage, self).__init__(driver)
        self._view_panel = SoftwareUpdatePageViewPanel(driver, download_checker)

    def load_software_package_from_local_drive(self, file_path, timeout):
        return self._view_panel.load_software_package_from_local_drive(file_path, timeout)

    def load_software_package_from_remote_server(self, url, sw_file, timeout):
        return self._view_panel.load_software_package_from_remote_server(url, sw_file, timeout)

    def software_update(self, is_activate, timeout, start_enable_timeout, **kwargs):
        self._view_panel.software_update(is_activate, timeout, start_enable_timeout, **kwargs)

    def operate_reload_modal(self, operation='Reload', timeout=60):
        self._view_panel.operate_reload_modal(operation, timeout)

    def cancel_software_update(self):
        self._view_panel.cancel_software_update()

    def check_software_update_progress(self):
        return self._view_panel.check_software_update_progress()

    def check_current_software_version(self, key):
        version = self._view_panel.get_all_current_software_version()
        return version if key is None else version[key]

    def save_sw_update_report(self, download_timeout):
        return self._view_panel.save_sw_update_report(download_timeout)

    def software_rollback(self):
        self._view_panel.software_rollback()

    def backup_bts_site_configuration(self, download_timeout):
        return self._view_panel.backup_bts_site_configuration(download_timeout)

    def _get_route_list(self):
        return self._MENU_ROUTE_LIST


class SoftwareUpdatePageViewPanel(ViewPanel):
    _LOCAL_DRIVE_RADIO_BOX_XPATH = "//label[contains(text(), 'Local drive')]"
    _REMOTE_SERVER_RADIO_BOX_XPATH = "//label[contains(text(), 'Remote server')]"
    _LOCAL_LOAD_HIDDEN_BUTTON_SCRIPT = "open-software-local ui-file-input input"
    _LOCAL_LOAD_HIDDEN_BUTTON_XPATH = "//*[text()=' Browse...']/../../input[@type='file']"
    _LOAD_INFO_XPATH = "//div[@class='package-info']/div"
    _LOAD_INFO_SUCCESS_XPATH = "//div[@class='package-info']//*[contains(text(), 'Software file check completed')]"
    _ACTIVATE_CHECKBOX_SELECTED_XPATH = "//input[@id='activate-checkbox']"
    _ACTIVATE_CHECKBOX_XPATH = "//input[@id='activate-checkbox']/../label"
    _START_UPDATE_BUTTON_XPATH = "//ui-button[@a-text='Start']/button[contains(text(), 'Start')]"
    _UPDATE_PROGRESS_CONTEXT_XPATH = "//div[@class='software-progress-root']//div[@class='cancel-info']//span"
    _UPDATE_PROGRESS_BAR_XPATH = "//div[contains(@class, 'progress-bar')]//span"
    _CANCEL_UPDATE_BUTTON_XPATH = "//button[contains(text(), 'Cancel')]"
    _VERSION_KEYS_XPATH = "//table[@class='current-table']//th"
    _VERSION_VALUES_XPATH = "//table[@class='current-table']//td[1]"
    _ROLLBACK_BUTTON_XPATH = "//button[contains(text(), 'Rollback...')]"
    _SAVE_SW_UPDATE_REPORT_BUTTON_XPATH = "//button[contains(text(),'Save SW Update Report')]"
    _BACKUP_CONFIGURATION_BUTTON = "//button[contains(text(), ' Backup BTS Site Configuration')]"
    _PACKAGE_TYPE_XPATH = '//software-info//tr[th[contains(text(), "Type")]]/td'
    _RESET_ORU_RADIO_SELECTED_XPATH = "//input[@id='reset-checkbox']"
    _RESET_ORU_RADIO_CHECKBOX_XPATH = "//input[@id='reset-checkbox']/../label"
    _PACKAGE_TYPE = None
    _PACKAGE_TYPE_SITE = "Site"
    _EXTERNAL_DEVICES = 'External devices'
    _ORU_TYPE = "O-RU SW"

    def __init__(self, driver, download_checker):
        super(SoftwareUpdatePageViewPanel, self).__init__(driver, download_checker)

    @property
    def package_type(self):
        return self._PACKAGE_TYPE

    @package_type.setter
    def package_type(self, value):
        self._PACKAGE_TYPE = value

    def load_software_package_from_local_drive(self, file_path, timeout):
        try:
            self.select_radiobox_by_xpath(self._LOCAL_DRIVE_RADIO_BOX_XPATH)
            self.load_file_from_hidden_button(self._LOCAL_LOAD_HIDDEN_BUTTON_SCRIPT,
                                              self._LOCAL_LOAD_HIDDEN_BUTTON_XPATH, file_path, timeout)
            self.wait_for_visibility_by_xpath(self._LOAD_INFO_SUCCESS_XPATH, timeout)
            self.package_type = self.get_text_by_xpath(self._PACKAGE_TYPE_XPATH)
            return "software package load success"
        except TimeoutException:
            error_text = self.get_text_by_xpath(self._LOAD_INFO_XPATH)
            if error_text:
                return error_text
            raise

    def load_software_package_from_remote_server(self, url, sw_file, timeout):
        self.select_radiobox_by_xpath(self._REMOTE_SERVER_RADIO_BOX_XPATH)
        # TODO it will be finished when test environment has been ready

    def software_update(self, is_activate, timeout, start_enable_timeout, **kwargs):
        logging.info("package type is {}".format(self._PACKAGE_TYPE))
        if self.package_type != self._EXTERNAL_DEVICES and self.package_type != self._ORU_TYPE:
            self.select_checkbox_by_specified_status(is_activate, self._ACTIVATE_CHECKBOX_SELECTED_XPATH,
                                                     self._ACTIVATE_CHECKBOX_XPATH)
        if self.package_type == self._ORU_TYPE:
            self.select_checkbox_by_specified_status(True, self._RESET_ORU_RADIO_SELECTED_XPATH,
                                                     self._RESET_ORU_RADIO_CHECKBOX_XPATH)
        self.click_enabled_element_after_visible((By.XPATH, self._START_UPDATE_BUTTON_XPATH), start_enable_timeout)
        logging.info('cpu use {} percent, memory use {} percent'.format(psutil.cpu_percent(),
                                                                        psutil.virtual_memory().percent))

        if self.package_type == self._PACKAGE_TYPE_SITE:
            self.operate_reload_modal(operation='Close', timeout=timeout)

    def operate_reload_modal(self, operation='Reload', timeout=6):
        reload_modal = WebElementManagerReloadModal(self.driver)
        reload_modal.wait_until_login_modal_appear(timeout)
        if operation == 'Close':
            reload_modal.confirm(timeout)
        if operation == 'Reload':
            reload_modal.reload(timeout)

    def cancel_software_update(self):
        self.click_enabled_element_after_visible((By.XPATH, self._CANCEL_UPDATE_BUTTON_XPATH))
        abort_software_download_modal = AbortSoftwareDownloadModal(self.driver)
        abort_software_download_modal.wait_until_abort_software_download_modal_appear()
        abort_software_download_modal.abort()

    def check_software_update_progress(self):
        text = self.get_text_by_xpath(self._UPDATE_PROGRESS_CONTEXT_XPATH)
        percentage = self.get_text_by_xpath(self._UPDATE_PROGRESS_BAR_XPATH)
        return {'status': text, 'percentage': percentage}

    def get_all_current_software_version(self):
        return self.get_dict_from_elements_by_xpath(self._VERSION_KEYS_XPATH, self._VERSION_VALUES_XPATH, ':')

    def software_rollback(self):
        self.click_enabled_element_after_visible((By.XPATH, self._ROLLBACK_BUTTON_XPATH))
        rollback_software_modal = RollbackSoftwareModal(self.driver)
        rollback_software_modal.wait_until_rollback_software_modal_appear()
        rollback_software_modal.rollback()

    def _download_files_by_xpath(self, xpath, download_timeout):
        start_time = time.time()
        self.click_enabled_element_after_visible((By.XPATH, xpath))
        return self.download_files(start_time, download_timeout)

    def save_sw_update_report(self, download_timeout):
        return self._download_files_by_xpath(self._SAVE_SW_UPDATE_REPORT_BUTTON_XPATH, download_timeout)

    def backup_bts_site_configuration(self, download_timeout):
        return self._download_files_by_xpath(self._BACKUP_CONFIGURATION_BUTTON, download_timeout)


class AntennaLineDevicesSoftwarePage(NavigatablePage):
    _MENU_ROUTE_LIST = ['Software', 'Software Management', 'Antenna Line Devices Software']

    def __init__(self, driver, download_checker):
        super(AntennaLineDevicesSoftwarePage, self).__init__(driver)
        self._view_panel = AntennaLineDevicesSoftwarePageViewPanel(driver, download_checker)

    def restore_hw_info(self, sw_file, target_sw_version, manufacturer, product_code, serial_number,
                        hw_version, sw_update_options, timeout, with_sn, ald_config_index):
        self._view_panel.restore_hw_info(sw_file=sw_file,
                                         target_sw_version=target_sw_version,
                                         manufacturer=manufacturer,
                                         product_code=product_code,
                                         serial_number=serial_number,
                                         hw_version=hw_version,
                                         sw_update_options=sw_update_options,
                                         timeout=timeout,
                                         with_sn=with_sn,
                                         ald_config_index=ald_config_index)

    def save_ald_sw_file(self, download_timeout=30):
        return self._view_panel.save_ald_sw_file(download_timeout)

    def _get_route_list(self):
        return self._MENU_ROUTE_LIST


class AntennaLineDevicesSoftwarePageViewPanel(ViewPanel):
    RESTORE_HW_INFO_WITH_SN = 'Restore HW Info with SN'
    RESTORE_HW_INFO_WITHOUT_SN = 'Restore HW Info without SN'
    ALD_RESTORE_HW_CHOOSE_BUTTON = '//ald-restore-hw-info//button[@role="button"]'
    ALD_RESTORE_HW_OPTION = '//ald-restore-hw-info//li//span'
    SHOW_INPUT_SELECTOR = '*[class="ald-config-table-root"] tbody tr:nth-child({}) ui-file-input input'
    FILE_INPUT_BUTTON = '//*[@class="ald-config-table-root"]//tbody//tr[{}]//*[@class="open-file-td"]//input'
    TABLE_TDS_INPUT = '//*[@class="ald-config-table-root"]//tbody//tr[{}]//input[contains(@ng-model, "{}")]'
    SW_UPDATE_BUTTON = '//*[@class="ald-config-table-root"]//tbody//tr[{}]//*[input[contains(@ng-model, "{}")]]//button'
    SW_UPDATE_OPTIONS = '//*[@class="ald-config-table-root"]//tbody//tr[{}]//*[input[contains(@ng-model, "{}")]]//li'
    SAVE_ALD_BUTTON = '//ald-software//button[contains(text(), "Save")]'
    PARAMS_ATTR_MAPPING = {
        'target_sw_version': 'swVersion',
        'manufacturer': 'manufacturer',
        'product_code': 'productCode',
        'serial_number': 'serialNumber',
        'hw_version': 'hwVersion',
        'sw_update_options': 'swUpdateOption'
    }

    def __init__(self, driver, download_checker):
        super(AntennaLineDevicesSoftwarePageViewPanel, self).__init__(driver, download_checker)

    def restore_hw_info(self, sw_file, target_sw_version, manufacturer=None, product_code=None,
                        serial_number=None, hw_version=None, sw_update_options=None,
                        timeout=60, with_sn=True, ald_config_index=1):
        params = locals()

        restore_way = self.RESTORE_HW_INFO_WITH_SN if with_sn else self.RESTORE_HW_INFO_WITHOUT_SN
        self.select_element_from_dropdown_list_by_text_and_click(restore_way,
                                                                 (By.XPATH, self.ALD_RESTORE_HW_CHOOSE_BUTTON),
                                                                 (By.XPATH, self.ALD_RESTORE_HW_OPTION))

        self.load_file_from_hidden_button_in_sbts(self.SHOW_INPUT_SELECTOR.format(ald_config_index),
                                                  self.FILE_INPUT_BUTTON.format(ald_config_index),
                                                  sw_file,
                                                  timeout)
        params.pop('self')
        params.pop('sw_file')
        params.pop('timeout')
        params.pop('with_sn')
        params.pop('ald_config_index')

        for name, value in params.items():
            mapping_name = self.PARAMS_ATTR_MAPPING[name]
            if name == 'sw_update_options' and sw_update_options is not None:
                sw_update_button = self.SW_UPDATE_BUTTON.format(ald_config_index, mapping_name)
                sw_update_option = self.SW_UPDATE_OPTIONS.format(ald_config_index, mapping_name)
                self.select_element_from_dropdown_list_by_text_and_click(value,
                                                                         (By.XPATH, sw_update_button),
                                                                         (By.XPATH, sw_update_option))
                continue

            if value is not None:
                param_input = self.TABLE_TDS_INPUT.format(ald_config_index, mapping_name)
                self.insert_text_to_enable_element((By.XPATH, param_input), value, timeout)

    def save_ald_sw_file(self, download_timeout=30):
        start_time = time.time()
        self.click_enabled_element_after_visible((By.XPATH, self.SAVE_ALD_BUTTON))
        return self.download_files(start_time, download_timeout)


class BeamSetRealizationSoftwarePage(NavigatablePage):
    _MENU_ROUTE_LIST = ['Software', 'Software Management', 'Beam Set Realization Software']

    def __init__(self, driver, download_checker):
        super(BeamSetRealizationSoftwarePage, self).__init__(driver)
        self._view_panel = BeamSetRealizationSoftwarePageViewPanel(driver, download_checker)

    def get_beam_set_realization_software_info(self, timeout):
        return self._view_panel.get_beam_set_realization_software_info(timeout)

    def delete_beam_set_realization_software_item(self, bsr_package_list):
        self._view_panel.delete_beam_set_realization_software_item(bsr_package_list)

    def _get_route_list(self):
        return self._MENU_ROUTE_LIST


class BeamSetRealizationSoftwarePageViewPanel(ViewPanel):
    _BEAM_SET_REALIZATION_SOFTWARE_HEADER_XPATH = ('//div[contains(@class, "bsr-general")]//table//thead'
                                                   '//th[not(contains(@class, "check-box"))]')
    _BEAM_SET_REALIZATION_SOFTWARE_ROW_XPATH = '//div[contains(@class, "bsr-general")]//table//tbody//tr'
    _DELETE_BUTTON_XPATH = "//*[@label='Beam Set Realization Software']//*[@ng-reflect-label='Delete']"
    _CHECKBOX_XPATH = ("//*[@label='Beam Set Realization Software']//tbody//tr"
                       "//div[contains(@class, 'checkbox') or contains(@role, 'checkbox')]")
    _CHECKBOX_XPATH_WITH_PACKAGE_NUMBER = ("//*[@label='Beam Set Realization Software']//tr[td[@title='{}']]"
                                           "//div[contains(@class, 'checkbox') or contains(@role, 'checkbox')]")
    _DELETE_TITLE_XPATH = '//header[@class="bsr-remove"]'

    def __init__(self, driver, download_checker):
        super(BeamSetRealizationSoftwarePageViewPanel, self).__init__(driver, download_checker)

    def get_beam_set_realization_software_info(self, timeout):
        bsr_value = []
        keys = self.get_fields_info_from_row(self._BEAM_SET_REALIZATION_SOFTWARE_HEADER_XPATH, timeout)
        try:
            wait_for_checkbox_appear_timeout = 10
            self.wait_for_visibility_by_xpath(self._CHECKBOX_XPATH, wait_for_checkbox_appear_timeout)
        except TimeoutException:
            return bsr_value

        for elem in self.driver.find_elements_by_xpath(self._BEAM_SET_REALIZATION_SOFTWARE_ROW_XPATH):
            values = [value_elem.text.strip() for value_elem in
                      elem.find_elements_by_xpath('td[not(contains(@class, "check-box"))]')]
            bsr_value.append(dict(zip(keys, values)))
        return bsr_value

    def delete_beam_set_realization_software_item(self, bsr_package_list):
        self.wait_for_visibility_by_xpath(self._DELETE_TITLE_XPATH)
        for bsr_package in bsr_package_list:
            checkbox_xpath = self._CHECKBOX_XPATH.format(bsr_package)
            self.wait_for_visibility_by_xpath(checkbox_xpath)
            self.select_checkbox_by_xpath(checkbox_xpath)
        self.click_enabled_element((By.XPATH, self._DELETE_BUTTON_XPATH))
